/** Each deprecated setting's deprecation text, by its dotted wire key. */
const DEPRECATED_SETTINGS: DeprecatedSettings = new Map([
  ["sample.echo_repeats", "Since 0.1, removed no earlier than 1.0: A sample setting, which the real catalog replaces."],
]);

/** @internal A scope's `settings` as the wire takes them; `undefined` when left out. */
export function settingsOnWire(settings: FoxhoundSettings | undefined): SettingsOnWire | undefined {
  return onWire(settings, SPELLING, DEPRECATED_SETTINGS);
}
